/* Exact native formation, presented over the existing adapted map/zoom. */
#define GENESIS_NO_MAIN
#include "../.local/source/build/dune-web.c"
#include "em_web_campaign.h"
#include <sys/stat.h>
static CPU c,before,isolate,without;static DuneMouse mouse;
static void check(int ok,const char*s){if(!ok){fprintf(stderr,"FAIL %s pc%x %s\n",s,c.pc,em_web_campaign_report(&c));exit(1);}}
static void step(void){if(!em_web_campaign_observe(&c))dune_mouse_observe(&mouse,&c);machine_step(&c);check(!c.fault,"original flyover flow healthy");}
static unsigned components(const uint8_t*m,unsigned w,unsigned h){uint8_t*seen=calloc(w*h,1);unsigned*q=malloc(w*h*sizeof*q),count=0;for(unsigned at=0;at<w*h;at++){if(!m[at]||seen[at])continue;unsigned first=0,end=0,area=0;q[end++]=at;seen[at]=1;while(first<end){unsigned p=q[first++],x=p%w,y=p/w;++area;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int xx=(int)x+dx,yy=(int)y+dy;if(xx<0||yy<0||xx>=(int)w||yy>=(int)h)continue;unsigned n=yy*w+xx;if(m[n]&&!seen[n]){seen[n]=1;q[end++]=n;}}}if(area>=32)++count;}free(q);free(seen);return count;}
int main(int argc,char**argv){int loss=argc>1&&!strcmp(argv[1],"loss");FILE*f=fopen(loss?".local/campaign-scenes/house1-mission01-pre-defeat.cpu.bin":".local/campaign-scenes/house1-mission01-pre-victory.cpu.bin","rb");check(f&&fread(&c,sizeof c,1,f)==1,"pre-outcome fixture");fclose(f);c.rom=rom_data;c.rom_size=sizeof rom_data;c.reason=NULL;c.fault=0;c.audio_mode=AUDIO_MUTE;memset(c.pad_buttons,0,sizeof c.pad_buttons);mouse.enabled=1;em_web_campaign_after_load(&c);uint64_t end=c.vdp.frames+1000;while(!(dune_long(&c,0xe002)==0xb544&&(int16_t)dune_word(&c,0xd308)>=111)&&c.vdp.frames<end)step();check(dune_long(&c,0xe002)==0xb544&&em_web_campaign_battle_presentation(&c)&&em_web_campaign_world_visible(&c),"native flyover retains adapted battle presentation");before=c;isolate=c;unsigned plane=0;for(unsigned node=dune_word(&c,0xf3ac),i=0;node&&i<512;i++,node=dune_word(&c,node+14)){check(node<=65520,"valid native render list");if(dune_long(&c,node)==0xffd306)plane=node;else isolate.ram[node+7]|=0x80;}check(plane&&dune_long(&c,plane+8)==0xb5fc,"original seven-plane formation descriptor");without=isolate;without.ram[plane+7]|=0x80;mkdir(".local/adapted-flyover",0755);mkdir(".local/adapted-flyover/loss",0755);
 const unsigned wh[][3]={{960,540,100},{960,540,50},{390,844,100},{390,844,50},{844,390,100},{844,390,50},{320,224,100}};for(unsigned n=0;n<sizeof wh/sizeof wh[0];n++){DuneLayout p=dune_view_layout(&c,wh[n][0],wh[n][1],wh[n][2]);p.left+=96;p.top+=32;DuneView v={0};v.cursor_hidden=!em_web_cursor_preview(&c);check(dune_view_build(&v,&isolate,&p),"actual DuneView terrain/sprite traversal");check(v.left==p.left&&v.top==p.top,"existing adapted camera/pan unchanged");size_t size=(size_t)v.width*v.height;uint8_t*mask=calloc(size,1),sprites[320*224];for(unsigned by=0;by<v.height;by+=192)for(unsigned bx=0;bx<v.width;bx+=256){check(dune_view_sprites(&v,&isolate,p.left+bx-32,p.top+by-16,sprites,0),"original formation projected into world chunks");unsigned bw=v.width-bx<256?v.width-bx:256,bh=v.height-by<192?v.height-by:192;for(unsigned y=0;y<bh;y++)for(unsigned x=0;x<bw;x++)mask[(by+y)*v.width+bx+x]=sprites[(y+16)*320+x+32]!=0;}unsigned count=components(mask,v.width,v.height);check(count==7,"exact seven original aircraft in full adapted viewport");check(dune_view_sprites(&v,&isolate,dune_word(&c,0xe3ec),dune_word(&c,0xe3ee),sprites,1),"separate native HUD pass");unsigned hud=0;for(unsigned i=0;i<320*224;i++)hud+=sprites[i]!=0;check(!hud,"formation is not duplicated or pinned into fixed HUD");char file[256];snprintf(file,sizeof file,".local/adapted-flyover/%s%ux%u-z%u.rgb",loss?"loss/":"",wh[n][0],wh[n][1],wh[n][2]);f=fopen(file,"wb");check(f!=NULL,"adapted native RGB evidence");fwrite(v.pixels,1,size*3,f);fclose(f);snprintf(file,sizeof file,".local/adapted-flyover/%s%ux%u-z%u.json",loss?"loss/":"",wh[n][0],wh[n][1],wh[n][2]);f=fopen(file,"w");fprintf(f,"{\"outputWidth\":%u,\"outputHeight\":%u,\"zoom\":%u,\"worldWidth\":%u,\"worldHeight\":%u,\"worldScale\":%.9f,\"left\":%d,\"top\":%d,\"nativeAircraft\":%u,\"nativePositionUnmodified\":true,\"hudAircraft\":0}",wh[n][0],wh[n][1],wh[n][2],v.width,v.height,p.world_scale,p.left,p.top,count);fclose(f);check(!memcmp(&before,&c,sizeof c),"viewport/zoom proof preserves entire native CPU");printf("PASS adapted flyover%ux%u zoom%u: seven planes, native sprites/world scale, camera(%d,%d), no HUD duplicate, CPU unchanged\n",wh[n][0],wh[n][1],wh[n][2],p.left,p.top);fflush(stdout);free(mask);free(v.shadow);free(v.pixels);free(v.ui);}return 0;}
